  -- 889 Chemical Reactions & Equations
  (889,'govt_technical','rxn-concept','concept',1,'रासायनिक अभिक्रिया — SSC JE / RRB JE',$j${"note":"JE में संतुलित समीकरण और अभिक्रिया के प्रकार अक्सर पूछे जाते हैं।","text":"रासायनिक अभिक्रिया में अभिकारक उत्पाद में बदलते हैं। समीकरण संतुलित होना चाहिए, यानी दोनों ओर हर परमाणु की संख्या बराबर हो। प्रकार: संयोजन, वियोजन, विस्थापन और द्वि-विस्थापन।"}$j$),
  (889,'govt_technical','rxn-formula','formula',2,'द्रव्यमान संरक्षण',$j${"formula":"अभिकारकों का कुल द्रव्यमान = उत्पादों का कुल द्रव्यमान","explanation":"रासायनिक अभिक्रिया में द्रव्यमान नष्ट या उत्पन्न नहीं होता (लेवोज़िए का नियम)"}$j$),
  (889,'govt_technical','rxn-example','example',3,'Numerical (JE style)',$j${"question":"4 g हाइड्रोजन और 32 g ऑक्सीजन से कितने g पानी बनेगा? (2H₂ + O₂ → 2H₂O)","solution":"द्रव्यमान संरक्षण से: 4 + 32 = 36 g","answer":"36 g"}$j$),
  (889,'govt_technical','rxn-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"CaCO₃ → CaO + CO₂ कौन सी अभिक्रिया है?","options":["वियोजन","संयोजन","विस्थापन","उदासीनीकरण"],"answer":0,"explanation":"एक यौगिक दो उत्पादों में टूटता है, इसलिए यह वियोजन अभिक्रिया है।"},{"q":"संतुलित समीकरण में क्या बराबर होना चाहिए?","options":["हर तत्व के परमाणुओं की संख्या","अभिकारकों के अणुओं की संख्या","उत्पादों के अणुओं की संख्या","ऊष्मा"],"answer":0,"explanation":"संतुलन के लिए दोनों ओर हर तत्व के परमाणु बराबर होने चाहिए।"}]}$j$),
  (889,'govt_basic','rxn-concept','concept',1,'रासायनिक अभिक्रिया',$j${"note":"परीक्षा में अभिक्रिया के प्रकार के नाम और उदाहरण पूछे जाते हैं।","text":"जब दो या अधिक पदार्थ मिलकर नए पदार्थ बनाते हैं, तो उसे रासायनिक अभिक्रिया कहते हैं। लोहे पर जंग लगना और दही जमना इसके उदाहरण हैं।"}$j$),
  (889,'govt_basic','rxn-formula','formula',2,'संतुलन का नियम',$j${"formula":"दोनों ओर परमाणुओं की संख्या बराबर","explanation":"उदाहरण: 2H₂ + O₂ → 2H₂O (हर ओर 4 H और 2 O)"}$j$),
  (889,'govt_basic','rxn-example','example',3,'उदाहरण',$j${"question":"Mg + O₂ → MgO को संतुलित करने पर Mg का गुणांक कितना होगा?","solution":"2Mg + O₂ → 2MgO; इसलिए Mg का गुणांक 2 है","answer":"2"}$j$),
  (889,'govt_basic','rxn-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"लोहे पर जंग लगना कैसी अभिक्रिया है?","options":["रासायनिक अभिक्रिया","भौतिक परिवर्तन","केवल गलन","केवल वाष्पन"],"answer":0,"explanation":"जंग लगने में लोहा ऑक्सीजन से मिलकर नया पदार्थ बनाता है, यह रासायनिक अभिक्रिया है।"},{"q":"दही जमना किस प्रकार का परिवर्तन है?","options":["रासायनिक","भौतिक","केवल गलन","केवल वाष्पन"],"answer":0,"explanation":"दूध से दही बनने में नए पदार्थ बनते हैं, इसलिए यह रासायनिक परिवर्तन है।"}]}$j$),
  (889,null,'rxn-diagram','svg',5,'अभिकारक से उत्पाद',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='40' width='80' height='40' fill='#60a5fa' rx='6'/><text x='60' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>अभिकारक</text><line x1='110' y1='60' x2='190' y2='60' stroke='#f59e0b' stroke-width='3'/><polygon points='190,60 180,55 180,65' fill='#f59e0b'/><rect x='200' y='40' width='80' height='40' fill='#14b8a6' rx='6'/><text x='240' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>उत्पाद</text><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>अभिक्रिया द्वारा नए पदार्थ</text></svg>","caption":"अभिकारक अभिक्रिया के बाद उत्पाद में बदल जाते हैं"}$j$),
  -- 890 Oxidation & Reduction
  (890,'govt_technical','redox-concept','concept',1,'ऑक्सीकरण और अपचयन — SSC JE / RRB JE',$j${"note":"JE में ऑक्सीकरण-अपचयन की पहचान और जंग के रसायन अक्सर पूछे जाते हैं।","text":"ऑक्सीकरण में पदार्थ इलेक्ट्रॉन खोता है या ऑक्सीजन जोड़ता है। अपचयन में पदार्थ इलेक्ट्रॉन ग्रहण करता है या ऑक्सीजन खोता है। दोनों हमेशा साथ-साथ होते हैं, इसलिए इन्हें रेडॉक्स अभिक्रिया कहते हैं।"}$j$),
  (890,'govt_technical','redox-formula','formula',2,'रेडॉक्स की पहचान',$j${"formula":"ऑक्सीकरण = e⁻ खोना / O जोड़ना; अपचयन = e⁻ ग्रहण / O खोना","explanation":"उदाहरण: CuO + H₂ → Cu + H₂O में H₂ ऑक्सीकृत और CuO अपचयित होता है"}$j$),
  (890,'govt_technical','redox-example','example',3,'Numerical (JE style)',$j${"question":"Zn + 2HCl → ZnCl₂ + H₂ में ऑक्सीकृत पदार्थ कौन सा है?","solution":"Zn इलेक्ट्रॉन खोकर Zn²⁺ बनता है, इसलिए Zn ऑक्सीकृत होता है","answer":"Zn (जिंक)"}$j$),
  (890,'govt_technical','redox-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"ऑक्सीकरण में पदार्थ क्या खोता है?","options":["इलेक्ट्रॉन","प्रोटॉन","न्यूट्रॉन","द्रव्यमान"],"answer":0,"explanation":"ऑक्सीकरण में पदार्थ इलेक्ट्रॉन खोता है।"},{"q":"अपचयन में क्या होता है?","options":["इलेक्ट्रॉन ग्रहण","इलेक्ट्रॉन खोना","केवल ऊष्मा","केवल प्रकाश"],"answer":0,"explanation":"अपचयन में पदार्थ इलेक्ट्रॉन ग्रहण करता है।"}]}$j$),
  (890,'govt_basic','redox-concept','concept',1,'ऑक्सीकरण और अपचयन',$j${"note":"परीक्षा में ऑक्सीकरण के उदाहरण और जंग का कारण पूछे जाते हैं।","text":"लोहे में जंग लगना ऑक्सीकरण का उदाहरण है। लोहा हवा की ऑक्सीजन और नमी से मिलकर आयरन ऑक्साइड बनाता है। कॉपर ऑक्साइड को हाइड्रोजन से गर्म करने पर ऑक्सीजन निकलती है, वह अपचयन है।"}$j$),
  (890,'govt_basic','redox-formula','formula',2,'ऑक्सीकरण की पहचान',$j${"formula":"ऑक्सीजन जुड़ना = ऑक्सीकरण","explanation":"ऑक्सीजन निकलना = अपचयन"}$j$),
  (890,'govt_basic','redox-example','example',3,'उदाहरण',$j${"question":"लोहे में जंग लगना किसका उदाहरण है?","solution":"लोहा ऑक्सीजन से जुड़कर ऑक्साइड बनाता है, इसलिए यह ऑक्सीकरण है","answer":"ऑक्सीकरण"}$j$),
  (890,'govt_basic','redox-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"जंग (rust) लगने से कौन सी धातु प्रभावित होती है?","options":["लोहा","सोना","चाँदी","प्लैटिनम"],"answer":0,"explanation":"लोहे में ऑक्सीकरण से जंग लगती है।"},{"q":"किसी ऑक्साइड से ऑक्सीजन निकल जाए तो क्या होता है?","options":["अपचयन","ऑक्सीकरण","गलन","वाष्पन"],"answer":0,"explanation":"ऑक्सीजन खोना अपचयन कहलाता है।"}]}$j$),
  (890,null,'redox-diagram','svg',5,'ऑक्सीकरण और अपचयन',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='30' y='40' width='100' height='40' fill='#f59e0b' rx='6'/><text x='80' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>ऑक्सीकरण</text><rect x='170' y='40' width='100' height='40' fill='#14b8a6' rx='6'/><text x='220' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>अपचयन</text><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>दोनों एक साथ होते हैं (रेडॉक्स)</text></svg>","caption":"ऑक्सीकरण और अपचयन हमेशा साथ-साथ होते हैं"}$j$),
  -- 891 Acids, Bases & Salts
  (891,'govt_technical','acid-concept','concept',1,'अम्ल, क्षार और लवण — SSC JE / RRB JE',$j${"note":"JE में pH का पैमाना और उदासीनीकरण अभिक्रिया अक्सर पूछी जाती है।","text":"अम्ल का pH 7 से कम, क्षार का pH 7 से अधिक और उदासीन पदार्थ का pH 7 होता है। अम्ल और क्षार मिलकर लवण और पानी बनाते हैं, इसे उदासीनीकरण कहते हैं। pH = −log[H⁺]।"}$j$),
  (891,'govt_technical','acid-formula','formula',2,'pH का सूत्र',$j${"formula":"pH = −log[H⁺]","explanation":"[H⁺] = हाइड्रोजन आयन सांद्रता (mol/L) · pH 0–14 के बीच, 7 उदासीन"}$j$),
  (891,'govt_technical','acid-example','example',3,'Numerical (JE style)',$j${"question":"किसी विलयन में [H⁺] = 10⁻³ mol/L है। pH कितना है और वह अम्लीय है या क्षारीय?","solution":"pH = −log(10⁻³) = 3; 7 से कम है, इसलिए अम्लीय","answer":"pH = 3, अम्लीय"}$j$),
  (891,'govt_technical','acid-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"HCl + NaOH → ? (उदासीनीकरण)","options":["NaCl + H₂O","NaCl + H₂","NaOH + HCl","Na + H₂O₂"],"answer":0,"explanation":"अम्ल और क्षार उदासीनीकरण में लवण (NaCl) और पानी देते हैं।"},{"q":"उदासीन विलयन का pH कितना होता है?","options":["7","0","14","3"],"answer":0,"explanation":"उदासीन विलयन का pH 7 होता है।"}]}$j$),
  (891,'govt_basic','acid-concept','concept',1,'अम्ल, क्षार और लवण',$j${"note":"परीक्षा में लिटमस टेस्ट और सामान्य उदाहरण पूछे जाते हैं।","text":"नींबू, सिरका और इमली अम्लीय हैं। साबुन और बेकिंग सोडा क्षारीय हैं। नीले लिटमस को लाल करने वाला पदार्थ अम्ल है। लाल लिटमस को नीला करने वाला क्षार है।"}$j$),
  (891,'govt_basic','acid-formula','formula',2,'pH का सामान्य नियम',$j${"formula":"pH < 7 अम्ल · pH = 7 उदासीन · pH > 7 क्षार","explanation":"pH का परास 0 से 14 तक है"}$j$),
  (891,'govt_basic','acid-example','example',3,'उदाहरण',$j${"question":"नीले लिटमस को लाल करने वाला विलयन कैसा होता है?","solution":"नीले लिटमस को लाल करना अम्ल का गुण है","answer":"अम्लीय"}$j$),
  (891,'govt_basic','acid-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"बेकिंग सोडा का स्वभाव कैसा है?","options":["क्षारीय","अम्लीय","उदासीन","इनमें से कोई नहीं"],"answer":0,"explanation":"बेकिंग सोडा (NaHCO₃) का विलयन हल्का क्षारीय होता है।"},{"q":"नींबू का स्वाद खट्टा क्यों होता है?","options":["उसमें अम्ल होता है","उसमें क्षार होता है","उसमें नमक होता है","उसमें चीनी होती है"],"answer":0,"explanation":"नींबू में सिट्रिक अम्ल होता है, इसलिए वह खट्टा होता है।"}]}$j$),
  (891,null,'acid-diagram','svg',5,'pH का पैमाना',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='50' width='260' height='24' fill='#ef4444' opacity='0.5'/><rect x='150' y='50' width='130' height='24' fill='#60a5fa' opacity='0.5'/><text x='40' y='100' fill='#64748b' font-size='11'>अम्ल (pH &lt; 7)</text><text x='150' y='100' fill='#64748b' font-size='11'>उदासीन = 7</text><text x='220' y='100' fill='#64748b' font-size='11'>क्षार (pH &gt; 7)</text></svg>","caption":"pH 7 से कम अम्लीय और 7 से अधिक क्षारीय होता है"}$j$),
  -- 892 Metals & Non-metals
  (892,'govt_technical','met-concept','concept',1,'धातु और अधातु — SSC JE / RRB JE',$j${"note":"JE में अभिक्रियाशीलता श्रेणी और धातुओं के गुण अक्सर पूछे जाते हैं।","text":"धातुएँ तापीय और विद्युत की अच्छी सुचालक होती हैं, आघातवर्ध्य और तन्य होती हैं। अधातुएँ सामान्यत: कुचालक और भंगुर होती हैं (ग्रेफाइट अपवाद है)। अभिक्रियाशीलता श्रेणी: K > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Hg > Ag > Au।"}$j$),
  (892,'govt_technical','met-formula','formula',2,'विस्थापन अभिक्रिया',$j${"formula":"Zn + CuSO₄ → ZnSO₄ + Cu","explanation":"अधिक अभिक्रियाशील धातु (Zn) कम अभिक्रियाशील (Cu) को लवण विलयन से विस्थापित करती है"}$j$),
  (892,'govt_technical','met-example','example',3,'Numerical (JE style)',$j${"question":"अभिक्रियाशीलता श्रेणी में Fe और Cu में कौन अधिक अभिक्रियाशील है? Fe, CuSO₄ विलयन में डालने पर क्या होगा?","solution":"Fe, Cu से अधिक अभिक्रियाशील है, इसलिए Fe, Cu को विस्थापित करेगा: Fe + CuSO₄ → FeSO₄ + Cu","answer":"Fe अधिक अभिक्रियाशील; Cu विस्थापित होगा"}$j$),
  (892,'govt_technical','met-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"सबसे कम अभिक्रियाशील धातु कौन सी है?","options":["सोना (Au)","पोटैशियम (K)","सोडियम (Na)","कैल्शियम (Ca)"],"answer":0,"explanation":"श्रेणी में सोना (Au) सबसे नीचे है, इसलिए सबसे कम अभिक्रियाशील है।"},{"q":"धातुओं का कौन सा गुण तार बनाने की क्षमता बताता है?","options":["तन्यता","भंगुरता","कुचालकता","वाष्पशीलता"],"answer":0,"explanation":"तन्यता (ductility) धातु को तार में खींचने की क्षमता है।"}]}$j$),
  (892,'govt_basic','met-concept','concept',1,'धातु और अधातु के गुण',$j${"note":"परीक्षा में धातु और अधातु के उदाहरण पूछे जाते हैं।","text":"तांबा, लोहा और सोना धातुएँ हैं। ऑक्सीजन, सल्फर और कार्बन अधातुएँ हैं। धातुएँ चमकदार होती हैं और बिजली चलाती हैं। अधातुएँ आमतौर पर चमकदार नहीं होतीं।"}$j$),
  (892,'govt_basic','met-formula','formula',2,'धातु के गुण',$j${"formula":"धातु: चमकदार, सुचालक, तन्य · अधातु: भंगुर, कुचालक","explanation":"ग्रेफाइट (कार्बन) अधातु होते हुए भी बिजली चलाता है"}$j$),
  (892,'govt_basic','met-example','example',3,'उदाहरण',$j${"question":"बिजली का तार किस प्रकार की धातु से बनता है?","solution":"तांबा सुचालक धातु है और तार बनाने योग्य है","answer":"तांबा (कॉपर)"}$j$),
  (892,'govt_basic','met-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"इनमें से कौन अधातु है?","options":["सल्फर","लोहा","तांबा","एल्युमिनियम"],"answer":0,"explanation":"सल्फर अधातु है, जबकि बाकी तीन धातुएँ हैं।"},{"q":"धातुएँ किस गुण के कारण पतली चादर बन जाती हैं?","options":["आघातवर्ध्यता","भंगुरता","कुचालकता","वाष्पशीलता"],"answer":0,"explanation":"आघातवर्ध्यता (malleability) के कारण धातुएँ हथौड़े से पीटकर चादर बन जाती हैं।"}]}$j$),
  (892,null,'met-diagram','svg',5,'धातु और अधातु',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='30' y='40' width='100' height='40' fill='#94a3b8' rx='6'/><text x='80' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>धातु</text><rect x='170' y='40' width='100' height='40' fill='#fde68a' rx='6'/><text x='220' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>अधातु</text><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>धातु सुचालक, अधातु कुचालक</text></svg>","caption":"धातु और अधातु के गुण एक-दूसरे से अलग होते हैं"}$j$),
  -- 893 Carbon & Its Compounds
  (893,'govt_technical','carb-concept','concept',1,'कार्बन और यौगिक — SSC JE / RRB JE',$j${"note":"JE में हाइड्रोकार्बन का सामान्य सूत्र और कार्यात्मक समूह अक्सर पूछे जाते हैं।","text":"कार्बन की संयोजकता 4 है और यह लंबी श्रृंखला बना सकता है (कैटेनेशन)। एल्केन Cₙ H₂ₙ₊₂ (सिंगल बंध), एल्कीन Cₙ H₂ₙ (दोहरा बंध), एल्काइन Cₙ H₂ₙ₋₂ (त्रिबंध)। एथेनॉल (C₂H₅OH) में −OH कार्यात्मक समूह है।"}$j$),
  (893,'govt_technical','carb-formula','formula',2,'एल्केन का सामान्य सूत्र',$j${"formula":"Cₙ H₂ₙ₊₂","explanation":"एल्केन (सिंगल बंध): n = 1 मेथेन (CH₄), n = 2 एथेन (C₂H₆), n = 4 ब्यूटेन (C₄H₁₀)"}$j$),
  (893,'govt_technical','carb-example','example',3,'Numerical (JE style)',$j${"question":"ब्यूटेन (C₄H₁₀) एल्केन है। इसमें कुल कितने हाइड्रोजन परमाणु हैं, सूत्र से निकालो।","solution":"n = 4 ⇒ H = 2×4 + 2 = 10","answer":"10 हाइड्रोजन परमाणु"}$j$),
  (893,'govt_technical','carb-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"कार्बन की संयोजकता कितनी होती है?","options":["4","2","3","1"],"answer":0,"explanation":"कार्बन की संयोजकता 4 है।"},{"q":"एथेनॉल में कौन सा कार्यात्मक समूह है?","options":["−OH (हाइड्रॉक्सिल)","−COOH","−CHO","−NH₂"],"answer":0,"explanation":"एथेनॉल (C₂H₅OH) में −OH समूह होता है।"}]}$j$),
  (893,'govt_basic','carb-concept','concept',1,'कार्बन यौगिक',$j${"note":"परीक्षा में कार्बन के उदाहरण और उनके उपयोग पूछे जाते हैं।","text":"कार्बन हीरे, ग्रेफाइट और कोयले के रूप में मिलता है। खाने की चीनी, तेल, प्लास्टिक और दवाएँ कार्बन यौगिक हैं। कार्बन यौगिकों को हाइड्रोकार्बन और उनके कार्यात्मक समूह से पहचाना जाता है।"}$j$),
  (893,'govt_basic','carb-formula','formula',2,'मेथेन का सूत्र',$j${"formula":"CH₄","explanation":"मेथेन (CH₄) सबसे सरल हाइड्रोकार्बन है और प्राकृतिक गैस का मुख्य घटक है"}$j$),
  (893,'govt_basic','carb-example','example',3,'उदाहरण',$j${"question":"घरेलू LPG और प्राकृतिक गैस का मुख्य घटक कौन सा है?","solution":"प्राकृतिक गैस का मुख्य घटक मेथेन (CH₄) है","answer":"मेथेन (CH₄)"}$j$),
  (893,'govt_basic','carb-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"इनमें से कौन कार्बन का एक रूप है?","options":["हीरा","लोहा","नमक","पानी"],"answer":0,"explanation":"हीरा, ग्रेफाइट और कोयला कार्बन के रूप हैं।"},{"q":"सिरके का मुख्य घटक कौन सा यौगिक है?","options":["एसिटिक अम्ल","एथेनॉल","मेथेन","ब्यूटेन"],"answer":0,"explanation":"सिरके में लगभग 5% एसिटिक अम्ल होता है।"}]}$j$),
  (893,null,'carb-diagram','svg',5,'कार्बन श्रृंखला',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='40' cy='60' r='12' fill='#64748b'/><circle cx='90' cy='60' r='12' fill='#64748b'/><circle cx='140' cy='60' r='12' fill='#64748b'/><circle cx='190' cy='60' r='12' fill='#64748b'/><line x1='52' y1='60' x2='78' y2='60' stroke='#0f172a' stroke-width='3'/><line x1='102' y1='60' x2='128' y2='60' stroke='#0f172a' stroke-width='3'/><line x1='152' y1='60' x2='178' y2='60' stroke='#0f172a' stroke-width='3'/><text x='115' y='112' text-anchor='middle' fill='#64748b' font-size='11'>कार्बन की श्रृंखला (कैटेनेशन)</text></svg>","caption":"कार्बन परमाणु एक-दूसरे से जुड़कर लंबी श्रृंखला बनाते हैं"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
